import{_ as e,o as n,c as s,a2 as r}from"./chunks/framework.CiQ1TEvV.js";const u=JSON.parse('{"title":"混合检索","description":"","frontmatter":{},"headers":[],"relativePath":"zh/features/hybrid-retrieval.md","filePath":"zh/features/hybrid-retrieval.md","lastUpdated":1785115728000}'),i={name:"zh/features/hybrid-retrieval.md"};function l(t,a,p,o,d,c){return n(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="混合检索" tabindex="-1">混合检索 <a class="header-anchor" href="#混合检索" aria-label="Permalink to &quot;混合检索&quot;">​</a></h1><p>纯向量检索擅长语义相似，但对文件名、缩写、数字、专有名词或精确短语并不总是可靠。纯 BM25 可能错过一个有用的同义改写。Mneme 保留两种检索信号。</p><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户问题</span></span>
<span class="line"><span>  → 查询拆解</span></span>
<span class="line"><span>  → 并发混合检索 / Graph RAG 扩展</span></span>
<span class="line"><span>  → chunk 去重和动态 Top-K</span></span>
<span class="line"><span>  → PDF anchor enrich</span></span>
<span class="line"><span>  → 带引用的、有边界的不可信文档上下文</span></span>
<span class="line"><span>  → LLM 回答 + 可验证来源</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h2><h3 id="语义搜索" tabindex="-1">语义搜索 <a class="header-anchor" href="#语义搜索" aria-label="Permalink to &quot;语义搜索&quot;">​</a></h3><ul><li><strong>Sentence Transformers</strong> 生成 embedding</li><li><strong>ChromaDB</strong> 提供余弦相似度语义检索</li><li>默认模型：<code>all-MiniLM-L6-v2</code>（未缓存时从 ModelScope 自动下载）</li></ul><h3 id="词法搜索" tabindex="-1">词法搜索 <a class="header-anchor" href="#词法搜索" aria-label="Permalink to &quot;词法搜索&quot;">​</a></h3><ul><li><strong>BM25</strong> 提供基于关键词的检索</li><li>自定义 tokenization 支持双语文本、大小写折叠和标点剥离</li><li>对未变更的 chunk 增量复用 BM25 tokenization</li></ul><h3 id="rrf-融合" tabindex="-1">RRF 融合 <a class="header-anchor" href="#rrf-融合" aria-label="Permalink to &quot;RRF 融合&quot;">​</a></h3><p>RRF（倒数排名融合）融合排序结果，而不是比较不可兼容的原始分数：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RRF 分数 = Σ 1 / (k + rank)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>RRF 简单且可解释。它不要求语义距离和 BM25 分数共享同一量纲。</p><h3 id="动态-top-k" tabindex="-1">动态 Top-K <a class="header-anchor" href="#动态-top-k" aria-label="Permalink to &quot;动态 Top-K&quot;">​</a></h3><p>融合后，Mneme 从分数 gap 中选取动态 Top-K：</p><ul><li>明显的 gap 成为天然截断点</li><li>配置的下界（<code>LLM_TOP_K_MIN</code>）和上界（<code>LLM_TOP_K_MAX</code>）在 gap 不够明显时仍然生效</li></ul><h2 id="检索质量" tabindex="-1">检索质量 <a class="header-anchor" href="#检索质量" aria-label="Permalink to &quot;检索质量&quot;">​</a></h2><p>这套设计让检索质量变得可度量。Recall@k、MRR、nDCG 可以作为回归信号，而不是依赖&quot;感觉回答更好了&quot;这种印象。仓库在 <code>benchmarks/</code> 下包含 benchmark 数据和 quality-gate 工具。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>Standard RAG（混合检索）最适合一般问答和广泛的文档集。对于跨文档关联问题，请使用 <a href="/MNEME/zh/features/graph-rag">Graph RAG</a>。</p>`,20)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
